function loadMath(){if(window.MathJax?.Hub){window.MathJax.Hub.Queue(['Typeset',window.MathJax.Hub]);return}if(window.mathLoading)return;window.mathLoading=true;const script=document.createElement('script');script.src='/vendor/MathJax/MathJax.js?config=TeX-AMS-MML_HTMLorMML-full';script.onload=()=>window.MathJax?.Hub?.Queue(['Typeset',window.MathJax.Hub]);script.onerror=()=>notify('Math typesetting files unavailable; LaTeX source remains intact');document.body.appendChild(script)}
